  'designFiles.documentTemplate.capabilityMarkdown': 'Nutze beliebiges Markdown: Überschriften, Tabellen, Checklisten, Links, Zitate, Codeblöcke und Bilder.',
  'designFiles.documentTemplate.capabilityAgent': 'Der OpenDesign-Agent kann diese Datei lesen, bearbeiten und als Projektkontext verwenden.',
  'designFiles.documentTemplate.capabilityImages': 'Füge Bilder ein oder ziehe Bilddateien in den Editor; hochgeladene Bilder werden an der Cursorposition eingefügt.',
  'designFiles.documentTemplate.scenarioHeading': 'Szenario-Leitfaden',
  'designFiles.documentTemplate.scenario.prototype': 'Skizziere für Prototypen das Produktziel, die Zielgruppe, Abläufe, Screens, Module, Interaktionszustände, responsive Breakpoints und Design-Tokens wie Farbe, Schrift, Abstand, Radius und Motion.',
  'designFiles.documentTemplate.scenario.wireframe': 'Beschreibe für Wireframes den Nutzerfluss, die Screen-Liste, die Layout-Hierarchie, Inhaltsblöcke, Einschränkungen für niedrige Detailtreue und die Fragen, die die Struktur vor dem visuellen Design klären soll.',
  'designFiles.documentTemplate.scenario.mobile': 'Liste für Mobile-Apps Zielplattformen, Screens, Navigationsmodell, Gesten, native Muster, Gerätegrößen, Zustände und mobile Design-Tokens auf.',
  'designFiles.documentTemplate.scenario.slideDeck': 'Schreibe für Folien eine seitenweise PPT-Gliederung: ein Abschnitt pro Folie mit Titel, Zweck, Kernaussage, Belegen, visueller Richtung, Sprechernotizen und Export-Anforderungen.',
  'designFiles.documentTemplate.scenario.document': 'Lege für Dokumente Zielgruppe, Ton, Abschnittsstruktur, Quellmaterial, Zitate oder Daten, Layout-Erwartungen und PDF-/Export-Anforderungen fest.',
  'designFiles.documentTemplate.scenario.image': 'Gib für Bilder Motiv, Seitenverhältnis, Komposition, visuellen Stil, Marken-Tokens, Referenzdateien und Ausschlüsse an.',
  'designFiles.documentTemplate.scenario.video': 'Entwirf für Video ein Storyboard mit Szenen, Timing, Untertiteln, Motion, Assets, Audio-Hinweisen und Ausgabeformat.',
  'designFiles.documentTemplate.scenario.hyperframes': 'Beschreibe für HyperFrames das HTML-Motion-Stück: Szenen, Timeline, Untertitel, audioreaktive Momente, Übergänge und Erfassungs-/Export-Anforderungen.',
  'designFiles.documentTemplate.scenario.audio': 'Lege für Audio die Stimm- oder Musikrichtung, Dauer, Stimmung, Skript oder Text, Tempo, Aussprachehinweise und den Verwendungszweck fest.',
  'designFiles.documentTemplate.scenario.liveArtifact': 'Beschreibe für Live-Artefakte Datenquellen, Aktualisierungsrhythmus, Widgets, Filter, Interaktionen, Leer-/Lade-/Fehlerzustände sowie Warnungen oder Automatisierungen.',
  'designFiles.documentTemplate.scenario.designSystem': 'Liste für Designsysteme Markenziele, Tokens, Typografie, Farbe, Abstände, Komponenten, Assets, Referenzen sowie Regeln auf, die zu befolgen oder zu vermeiden sind.',
