  'nextStep.createDesignSystemTitle': 'Designsystem erstellen',
  'nextStep.createDesignSystemBody': 'Dupliziere dieses Projekt in einen Designsystem-Workspace und starte einen Agentenlauf mit allen aktuellen Dateien und Referenzen.',
  'nextStep.createDesignSystemBusy': 'Designsystem wird erstellt...',
  'nextStep.contribute': 'Beitragen',
  'nextStep.planGenerateTitle': "Generate from document",
  'nextStep.planGenerateBody': 'Nutze den freigegebenen Markdown-Plan als maßgebliche Quelle für den nächsten Design-Lauf.',
  'nextStep.planImproveTitle': 'Dokument verbessern',
  'nextStep.planImproveBody': 'Schärfe das aktuelle Plandokument, bevor du das finale Artefakt erzeugst.',
  'nextStep.planGeneratePrompt': 'Nutze `{file}` als maßgebliche Quelle. Lies zuerst das Dokument, übernimm seine Entscheidungen und erzeuge dann das finale Design-Artefakt, das dazu passt. Bei einer Folien-Gliederung erzeuge das Deck; bei einem PRD oder Prototyp-Plan erzeuge den Prototyp oder die Wireframes; bei einem Storyboard oder kreativen Briefing erzeuge das passende visuelle oder Medien-Artefakt. Weise vor der Erzeugung auf blockierende TODOs oder Widersprüche hin, die du nicht auflösen kannst.',
  'nextStep.planImprovePrompt': 'Lies `{file}` und verbessere es direkt als bearbeitbares Plandokument. Schärfe den Umfang, fülle schwache Abschnitte, ergänze fehlende Abnahmeprüfungen und behalte TODOs und offene Fragen, wo noch Eingaben des Nutzers fehlen. Erzeuge das finale Design-Artefakt noch nicht.',
  'nextStep.planImproveArtifactTitle': 'Artefakt verbessern',
  'nextStep.planImproveArtifactBody': 'Iteriere weiter am erzeugten Artefakt, statt zur Planung zurückzugehen.',
  'nextStep.planImproveArtifactPrompt': 'Verbessere `{artifact}` direkt. Behalte das bestehende funktionierende Artefakt und nimm die wirkungsvollsten Verbesserungen bei Produkt, Optik, Interaktion und Inhalt vor. Erhalte bereits funktionierendes Verhalten und fasse dann die geänderten Dateien und verbleibende Risiken zusammen.',
  'nextStep.planMergeTitle': 'Dokument und Artefakt abgleichen',
  'nextStep.planMergeBody': 'Gleiche Plan und erzeugtes Artefakt ab, damit beide gemeinsam vorankommen.',
  'nextStep.planMergePrompt': 'Lies `{document}` und `{artifact}` gemeinsam. Betrachte das Dokument als Absicht und das Artefakt als aktuelle Umsetzung. Gleiche beide ab: Passe das Artefakt an bestätigte Entscheidungen an, ändere das Dokument nur, wo es veraltet ist, und behalte ausdrückliche TODOs und offene Fragen für alles Ungeklärte. Erhalte funktionierendes Verhalten und fasse zusammen, was sich in beiden Dateien geändert hat.',

  'nextStep.projectContinueTitle': 'Weiterarbeiten',
